 const F=(key,label,type='text',options=null,required=false)=>({key,label,type,options,required});
 const schemas={
  task:{label:'İş / hatırlatma',group:'tasks',fields:[F('category','Konu','select',{general:'Genel',training:'Eğitim',health:'Sağlık',inspection:'Kontrol',emergency:'Acil durum',document:'Evrak'}),F('priority','Öncelik','select',{normal:'Normal',high:'Yüksek',critical:'Kritik'}),F('description','Yapılacak iş','textarea',null,true),F('completionEvidence','Tamamlanma bilgisi / kanıt','textarea'),F('verificationNote','Kontrol / doğrulama notu','textarea')]},
  personDocument:{label:'Personel belgesi / sağlık durumu',group:'people',fields:[F('kind','Belge türü','select',{training:'İSG eğitimi',medical:'Sağlık uygunluk durumu',vocational:'Mesleki yeterlilik',operator:'Operatör belgesi',firstAid:'İlk yardım',other:'Diğer'},true),F('documentNo','Belge numarası'),F('issuer','Düzenleyen kişi / kurum'),F('validFrom','Belge / muayene tarihi','date'),F('validUntil','Geçerlilik / sonraki kontrol','date'),F('fitStatus','Sağlık uygunluk durumu','select',{assessmentPending:'Değerlendirme bekliyor',suitable:'Uygun',restricted:'Hekim değerlendirmesi gerekli'}),F('notes','Not','textarea')]},
  training:{label:'Eğitim',group:'training',fields:[F('subject','Eğitim konusu','textarea',null,true),F('hours','Süre (saat)','number',null,true),F('trainer','Eğitmen adı','text',null,true),F('trainerQualification','Eğitmen yetkisi / unvanı'),F('method','Yöntem','select',{classroom:'Yüz yüze',practice:'Uygulamalı',distance:'Uzaktan',mixed:'Karma'}),F('location','Eğitim yeri'),F('trainingVerified','Eğitim gerçekleşti; katılım ve değerlendirme kontrol edildi','checkbox'),F('notes','Eğitim notu','textarea')]},
  equipment:{label:'Ekipman',group:'equipment',fields:[F('category','Ekipman türü','select',{lifting:'Kaldırma / iletme',pressure:'Basınçlı kap',electrical:'Elektrik tesisatı',grounding:'Topraklama',fire:'Yangın ekipmanı',machine:'İş makinesi',other:'Diğer'}),F('serialNo','Seri / ekipman numarası'),F('location','Bulunduğu yer','text',null,true),F('manufacturer','Üretici'),F('model','Model'),F('inServiceDate','Kullanıma giriş','date'),F('vehicleId','İlgili araç','vehicle'),F('notes','Ekipman notu','textarea')]},
  inspection:{label:'Periyodik kontrol',group:'equipment',fields:[F('controlKind','Kontrol konusu'),F('inspectionDate','Gerçek kontrol tarihi','date',null,true),F('reportNo','Kontrol rapor numarası'),F('controller','Kontrolü yapan kişi / kuruluş'),F('controllerRegistration','Yetki / kayıt numarası'),F('qualified','Kontrolü yapanın yetkisi doğrulandı','checkbox'),F('result','Kontrol sonucu','select',{pending:'Rapor bekleniyor',suitable:'Uygun',conditional:'Koşullu / takip gerekli',unsuitable:'Uygun değil'}),F('findings','Tespit / uygunsuzluklar','textarea'),F('notes','Not','textarea')]},
  risk:{label:'Risk / uygunsuzluk',group:'risks',fields:[F('hazard','Tehlike','textarea',null,true),F('consequence','Olası sonuç','textarea',null,true),F('probability','Olasılık (1–5)','number',null,true),F('severity','Şiddet (1–5)','number',null,true),F('existingMeasures','Mevcut önlemler','textarea'),F('measures','Alınacak önlemler','textarea',null,true),F('reviewDate','Yeniden değerlendirme','date'),F('notes','Not','textarea')]},
  action:{label:'Düzeltici faaliyet',group:'risks',fields:[F('relatedRecordId','İlgili risk / kayıt','record'),F('actionText','Yapılacak düzeltme','textarea',null,true),F('completionEvidence','Yapılan iş / kanıt','textarea'),F('verificationNote','Doğrulama / kapanış notu','textarea')]},
  emergencyTeam:{label:'Acil durum ekibi',group:'emergency',fields:[F('role','Ekip görevi','select',{firstAid:'İlk yardım',fire:'Yangınla mücadele',evacuation:'Tahliye',searchRescue:'Arama / kurtarma',other:'Diğer'},true),F('leaderId','Ekip sorumlusu','person'),F('notes','Görevlendirme / yeterlilik notu','textarea')]},
  drill:{label:'Tatbikat',group:'emergency',fields:[F('scenario','Senaryo','textarea',null,true),F('location','Tatbikat yeri','text',null,true),F('startTime','Başlangıç saati','time'),F('minutes','Süre (dakika)','number'),F('coordinator','Koordinatör'),F('findings','Gözlemler / eksikler','textarea'),F('improvements','İyileştirmeler','textarea'),F('notes','Not','textarea')]},
  incident:{label:'İş kazası / ramak kala',group:'incidents',fields:[F('kind','Olay türü','select',{accident:'İş kazası',nearMiss:'Ramak kala'},true),F('eventTime','Olay saati','time'),F('location','Olay yeri','text',null,true),F('description','Olay açıklaması','textarea',null,true),F('injuryStatus','Sağlık değerlendirmesi','select',{none:'Yaralanma bildirilmedi',medicalAssessmentRequired:'Hekim değerlendirmesi gerekli',handledByDoctor:'Hekime yönlendirildi'}),F('affectedCount','Etkilenen kişi sayısı','number'),F('immediateMeasures','İlk alınan önlemler','textarea'),F('rootCause','Kök neden / inceleme','textarea'),F('correctiveAction','Önleyici faaliyet','textarea'),F('sgkRequired','SGK bildirim takibi gerekiyor','checkbox'),F('sgkDeadline','Uzman tarafından belirlenen bildirim son tarihi','date'),F('sgkStatus','SGK takip durumu','select',{notRequired:'Gerekli değil',pending:'Bildirim bekliyor',submitted:'Bildirim yapıldı',verified:'Bildirim doğrulandı'}),F('sgkReference','Bildirim referansı'),F('sgkNotificationDate','Bildirim tarihi','date'),F('notes','Takip notu','textarea')]},
  measurement:{label:'Ortam ölçümü',group:'measurements',fields:[F('kind','Ölçüm türü','select',{dust:'Toz',noise:'Gürültü',vibration:'Titreşim',lighting:'Aydınlatma',chemical:'Kimyasal',thermal:'Termal konfor',other:'Diğer'},true),F('location','Ölçüm yeri','text',null,true),F('lab','Laboratuvar / kuruluş'),F('reportNo','Rapor numarası'),F('measuredValue','Ölçüm değeri'),F('unit','Birim'),F('referenceValue','Rapordaki referans / sınır'),F('result','Rapor sonucu','select',{pending:'Değerlendirme bekliyor',suitable:'Uygun',followUp:'İyileştirme / takip gerekli'}),F('notes','Uzman değerlendirmesi','textarea')]},
  provider:{label:'OSGB / hizmet sağlayıcı',group:'providers',fields:[F('providerName','Kuruluş / kişi','text',null,true),F('serviceKind','Hizmet','select',{osgb:'OSGB',specialist:'İSG uzmanı',doctor:'İşyeri hekimi',lab:'Laboratuvar',inspection:'Kontrol kuruluşu',other:'Diğer'}),F('contactName','İlgili kişi'),F('phone','Telefon','tel'),F('email','E-posta','email'),F('contractStart','Sözleşme başlangıcı','date'),F('contractEnd','Sözleşme bitişi','date'),F('notes','Hizmet notu','textarea')]},
  visit:{label:'Uzman / hekim ziyareti',group:'providers',fields:[F('providerId','Hizmet sağlayıcı','provider'),F('visitKind','Ziyaret türü','select',{specialist:'İSG uzmanı',doctor:'İşyeri hekimi',other:'Diğer'}),F('hours','Süre (saat)','number'),F('recommendations','Öneri / yapılacak işler','textarea',null,true),F('notes','Ziyaret notu','textarea')]},
  annualPlan:{label:'Yıllık çalışma / eğitim planı',group:'providers',fields:[F('year','Yıl','number',null,true),F('planKind','Plan türü','select',{work:'Yıllık çalışma planı',training:'Yıllık eğitim planı',evaluation:'Yıllık değerlendirme'}),F('notes','Plan açıklaması','textarea')]},
  document:{label:'İSG evrakı',group:'documents',fields:[F('kind','Belge konusu','select',{riskAssessment:'Risk değerlendirmesi',emergencyPlan:'Acil durum planı',instruction:'Talimat',contract:'Sözleşme',other:'Diğer'}),F('documentNo','Belge numarası'),F('issuer','Düzenleyen'),F('validFrom','Düzenlenme tarihi','date'),F('validUntil','Gözden geçirme / geçerlilik','date'),F('notes','Açıklama','textarea')]}
 };
 const tabs=[['overview','Takip'],['people','Personel'],['training','Eğitimler'],['equipment','Ekipman / Kontroller'],['risks','Risk / Faaliyet'],['emergency','Acil Durum'],['incidents','Olaylar'],['measurements','Ölçümler'],['providers','OSGB / Plan'],['documents','Evrak / Formlar']];
 const renewalKinds=[['training','Eğitim'],['medical','Sağlık değerlendirmesi'],['vocational','Mesleki belge'],['operator','Operatör belgesi'],['firstAid','İlk yardım'],['inspection','Periyodik kontrol']];
 const S={records:[],people:[],branches:[],vehicles:[],kkd:[],users:[],activity:[],settings:{},permissions:{},view:'overview',filters:{query:'',branch:'',status:'',from:'',to:'',type:'',archive:false,deadline:''},loaded:false,loading:false,busy:false,error:'',company:'',revision:0};
 let app=null,dialog=null,previousFocus=null,settingsHost=null,settingsForm=null,settingsDirty=false,settingsDraft=null,settingsDraftRevision=null,settingsRenderedBranches=[],settingsSaving=null,refreshPromise=null,loadSequence=0,sessionEpoch=0;
 const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const displayDate=v=>/^\d{4}-\d{2}-\d{2}/.test(v||'')?String(v).slice(0,10).split('-').reverse().join('.'):v||'—';
 const personName=p=>p?.name||p?.adSoyad||p?.adsoyad||[p?.ad,p?.soyad].filter(Boolean).join(' ')||p?.isim||'İsimsiz personel';
 const personBranch=p=>p?.branch||p?.sube||p?.subeAdi||'';
 const personId=p=>String(p?.id??p?.personelId??p?.personel_id??'');
 const branchName=b=>typeof b==='string'?b:b?.name||b?.ad||b?.subeAdi||b?.id||'';
 const userName=id=>{const u=S.users.find(x=>String(x.id)===String(id));return u?.name||u?.adSoyad||u?.username||S.people.find(x=>personId(x)===String(id))&&personName(S.people.find(x=>personId(x)===String(id)))||'—';};
 const can=(key)=>S.permissions.read===true&&!S.permissions.mustChangePassword&&S.permissions[key]===true;
 const canSettings=key=>S.permissions.role==='Admin'&&can(key);
 const mayEdit=()=>S.permissions.read===true&&S.permissions.write===true&&!S.permissions.mustChangePassword;
 const active=r=>!r.archivedAt&&r.status!=='cancelled';
 const done=r=>['completed','approved','closed','cancelled'].includes(r.status);
 function deadline(r){if(!r.dueDate||done(r))return '';const now=today();if(r.dueDate<now)return 'overdue';const days=Math.round((Date.parse(r.dueDate+'T12:00:00Z')-Date.parse(now+'T12:00:00Z'))/86400000);const reminder=Array.isArray(S.settings.reminderDays)?Math.max(0,...S.settings.reminderDays):Number(S.settings.reminderDays)||30;return days<=reminder?'soon':'';}
 function notice(text,type='success'){if(settingsHost)settingsNotice(text,type);if(typeof root.showToast==='function')root.showToast(text,type);else if(app){const message=app.querySelector('[data-isg-message]');if(message)message.textContent=text;}}
 function settingsNotice(text,type='success'){const message=settingsHost?.querySelector('[data-isg-settings-message]');if(message){message.textContent=text;message.className=type==='error'?'isg-error':'isg-settings-success';message.setAttribute('role',type==='error'?'alert':'status');}}
 async function api(action,payload={}){if(typeof root.fdIsgApi!=='function')throw new Error('İSG bağlantısı hazır değil. Uygulamayı yenileyin.');const epoch=sessionEpoch,result=await root.fdIsgApi(action,payload);if(epoch!==sessionEpoch)throw new Error('Oturum değişti. İSG sayfasını yeniden açın.');if(result?.success===false||result?.error)throw Object.assign(new Error(result.message||result.error?.message||result.error||'İşlem tamamlanamadı.'),{code:result.code||result.error?.code});return result?.result??result;}
 function mount(host){app=document.getElementById('isgApp');if(!app){app=document.createElement('div');app.id='isgApp';(host instanceof Element?host:document.body).appendChild(app);}app.style.display='block';app.onclick=onAppClick;app.oninput=onAppInput;app.onchange=onAppChange;return app;}
 async function open(host){mount(host);if(S.loaded){render();return;}await refresh();}
 async function refresh(){if(S.loading)return refreshPromise;S.loading=true;S.error='';const seq=++loadSequence;render();refreshPromise=(async()=>{try{const b=await api('bootstrap');if(seq!==loadSequence)return;S.records=Array.isArray(b.records)?b.records:[];S.people=Array.isArray(b.people)?b.people:[];S.branches=Array.from(new Set((Array.isArray(b.branches)?b.branches:[]).map(branchName).filter(Boolean)));S.users=b.users||b.owners||[];S.vehicles=b.vehicles||[];S.kkd=b.kkd||[];S.settings=b.settings||{};S.permissions=b.permissions||{};S.activity=b.activity||[];S.company=typeof b.company==='object'?b.company.name||'İşyeri':b.company||root.firmaAdi||'İşyeri';S.revision=b.settings?.revision||0;S.loaded=true;if(S.filters.branch&&!S.branches.includes(S.filters.branch))S.filters.branch='';if(!tabs.some(([key])=>key===S.view))S.view='overview';}catch(err){if(seq===loadSequence)S.error=err.message;}finally{if(seq===loadSequence){S.loading=false;render();}}})();return refreshPromise;}
 function options(values,value,empty='Seçiniz'){const list=Array.isArray(values)?values.map(x=>[x,x]):Object.entries(values||{});return (empty===null?'':`<option value="">${e(empty)}</option>`)+list.map(([k,v])=>`<option value="${e(k)}" ${String(value??'')===String(k)?'selected':''}>${e(v)}</option>`).join('');}
 function filtered(){const f=S.filters;return S.records.filter(r=>{if(Boolean(r.archivedAt)!==f.archive)return false;if(S.view!=='overview'&&S.view!=='people'&&S.view!=='settings'&&schemas[r.type]?.group!==S.view)return false;if(f.branch&&r.branch!==f.branch)return false;if(f.type&&r.type!==f.type)return false;if(f.status&&r.status!==f.status)return false;if(f.deadline==='overdue'&&deadline(r)!=='overdue')return false;if(f.deadline==='soon'&&deadline(r)!=='soon')return false;if(f.deadline==='open'&&done(r))return false;if(f.from&&(r.recordDate||'')<f.from)return false;if(f.to&&(r.recordDate||'')>f.to)return false;if(f.query&&!norm([r.title,r.branch,schemas[r.type]?.label,userName(r.ownerId),...Object.values(r.data||{}).filter(x=>typeof x!=='object'),...(r.personIds||[]).map(id=>personName(S.people.find(p=>personId(p)===String(id))))].join(' ')).includes(norm(f.query)))return false;return true;}).sort((a,b)=>{const aa=deadline(a)==='overdue'?0:done(a)?2:1,bb=deadline(b)==='overdue'?0:done(b)?2:1;return aa-bb||String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999'))||String(b.recordDate||'').localeCompare(String(a.recordDate||''));});}
 function statusHtml(r){const late=deadline(r)==='overdue';return `<span class="isg-badge ${e(late?'overdue':r.status)}">${e(late?'Gecikmiş · '+(statuses[r.status]||r.status):statuses[r.status]||r.status||'Planlandı')}</span>`;}
 function render(){renderSettingsHost();if(!app)return;app.innerHTML=`<header class="isg-header"><div><h2>İş Sağlığı ve Güvenliği</h2><p>Şube, personel ve ekipman bazında işler, belgeler ve tamamlanma takibi.</p></div><div class="isg-actions"><button data-act="refresh" ${S.loading?'disabled':''}>${S.loading?'Yenileniyor…':'Yenile'}</button><button data-act="output" data-fd-output-own="true">Çıktı</button>${mayEdit()?'<button class="isg-primary" data-act="new">+ Yeni Kayıt</button>':''}</div></header><nav class="isg-nav" aria-label="İSG bölümleri">${tabs.map(([k,t])=>`<button data-act="tab" data-view="${k}" ${S.view===k?'aria-current="page"':''}>${t}</button>`).join('')}</nav><div data-isg-message role="status" class="isg-muted" aria-live="polite"></div>${S.error?`<div class="isg-error" role="alert">${e(S.error)} <button data-act="refresh">Tekrar dene</button></div>`:''}${!S.loaded?`<div class="isg-panel isg-empty"><strong>${S.loading?'İSG kayıtları yükleniyor…':'İSG kayıtları yüklenemedi'}</strong>${S.loading?'Lütfen bekleyin.':'Bağlantıyı yenileyerek tekrar deneyebilirsiniz.'}</div>`:renderMain()}`;}
 function renderMain(){const records=S.records.filter(active).filter(r=>!S.filters.branch||r.branch===S.filters.branch);const counters=[['open','Açık işler',records.filter(r=>!done(r)).length,''],['overdue','Geciken',records.filter(r=>deadline(r)==='overdue').length,'isg-late'],['soon','Yaklaşan tarihler',records.filter(r=>deadline(r)==='soon').length,'isg-soon'],['review','Doğrulama bekliyor',records.filter(r=>r.status==='pending').length,'']];const list=filtered();const title=tabs.find(x=>x[0]===S.view)?.[1]||'Takip';return `${S.view==='overview'?`<section class="isg-strip" aria-label="İSG durum özeti">${counters.map(([k,l,n,c])=>`<button data-act="counter" data-value="${k}" class="${c}"><strong>${n}</strong><span>${l}</span></button>`).join('')}</section>`:''}${S.view==='people'?'<div class="isg-notice">Bu ekran belge ve sağlık uygunluk durumlarını gösterir. Tanı, tetkik ve ayrıntılı sağlık dosyaları yalnız yetkili işyeri hekimine açıktır.</div>':''}${S.view==='equipment'?'<div class="isg-notice">Periyodik kontrol kayıtları bakım kaydından ayrıdır. Kontrol raporu, yetkili kontrolör ve rapor sonucuyla takip edilir.</div>':''}${S.view==='incidents'?'<div class="isg-notice">Olay ve SGK bildirim durumunu takip edin. Bu ekranda kayıt oluşturmak resmî bildirim yerine geçmez; bildirim ayrı kanaldan yapılmalıdır.</div>':''}<section class="isg-panel"><div class="isg-panel-head"><div><h3>${e(title==='Takip'?'Yapılacak İşler ve Kayıtlar':title)}</h3><p class="isg-muted">${S.view==='people'?'Personel bazında eksik ve süresi yaklaşan belgeler.':S.filters.archive?'Arşivlenen kayıtlar; geçmiş korunur.':'Kaydın üzerine basarak ayrıntı, ekler ve değişiklik geçmişini açın.'}</p></div><div class="isg-actions">${S.view==='people'?'<button data-act="person-list">Belge Kayıtları</button>':''}${S.view==='documents'?'<button data-act="forms">Form Hazırla</button>':''}<label class="isg-check"><input data-filter="archive" type="checkbox" ${S.filters.archive?'checked':''}> Arşiv</label></div></div>${filterHtml()}<div class="isg-table-wrap">${S.view==='people'&&!S.filters.archive&&!S.filters.type?renderMatrix():recordTable(list)}</div><footer class="isg-footer"><span>${S.view==='people'&&!S.filters.type?matrixPeople().length+' personel':list.length+' kayıt'} · Son tarihler uzman / hekim tarafından doğrulanmalıdır.</span><span>Kaydetmek belgeyi imzalamış veya işlemi gerçekleştirmiş saymaz.</span></footer></section>`;}
 function filterHtml(){const f=S.filters;const types=Object.entries(schemas).filter(([,v])=>S.view==='overview'||S.view==='people'?S.view!=='people'||v.group==='people':v.group===S.view).map(([k,v])=>[k,v.label]);return `<div class="isg-filters"><label>Ara<input data-filter="query" value="${e(f.query)}" placeholder="İş, personel, ekipman veya belge ara"></label><label>Şube<select data-filter="branch">${options(S.branches,f.branch,'Tüm şubeler')}</select></label><label>Durum<select data-filter="status">${options(statuses,f.status,'Tüm durumlar')}</select></label><label>Başlangıç<input data-filter="from" type="date" value="${e(f.from)}"></label><label>Bitiş<input data-filter="to" type="date" value="${e(f.to)}"></label><button class="isg-filter-clear" data-act="clear">Temizle</button><label>Kayıt türü<select data-filter="type">${options(Object.fromEntries(types),f.type,'Tüm türler')}</select></label>${f.deadline?`<span class="isg-check isg-muted">${e({open:'Açık işler',overdue:'Geciken işler',soon:'Yaklaşan tarihler'}[f.deadline])}</span>`:''}</div>`;}
 function recordTable(list){return `<table><colgroup><col style="width:10%"><col style="width:26%"><col style="width:13%"><col style="width:13%"><col style="width:10%"><col style="width:13%"><col style="width:15%"></colgroup><thead><tr><th>Tür</th><th>Kayıt / Yapılacak İş</th><th>Şube</th><th>Sorumlu</th><th>Son Tarih</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${list.length?list.map(r=>`<tr><td>${e(schemas[r.type]?.label||r.type)}</td><td><button class="isg-record-title" data-act="detail" data-id="${e(r.id)}">${e(r.title)}</button><span class="isg-row-sub">${displayDate(r.recordDate)}${r.personIds?.length?' · '+r.personIds.length+' personel':''}</span></td><td>${e(r.branch)}</td><td>${e(userName(r.ownerId))}</td><td>${displayDate(r.dueDate)}</td><td>${statusHtml(r)}</td><td><div class="isg-actions"><button data-act="detail" data-id="${e(r.id)}">Aç</button>${mayEdit()&&!r.archivedAt?`<button data-act="edit" data-id="${e(r.id)}">Düzenle</button>`:''}${mayEdit()&&r.archivedAt?`<button data-act="restore" data-id="${e(r.id)}">Geri Al</button>`:''}</div></td></tr>`).join(''):'<tr><td colspan="7"><div class="isg-empty"><strong>Kayıt bulunmuyor</strong>Yeni kayıt ekleyebilir veya filtreleri değiştirebilirsiniz.</div></td></tr>'}</tbody></table>`;}
 function latestDocument(id,kind){return S.records.filter(r=>!r.archivedAt&&r.status!=='cancelled'&&(r.personIds||[]).some(p=>String(p)===String(id))&&((r.type==='personDocument'&&r.data?.kind===kind)||(kind==='training'&&r.type==='training'&&['completed','approved','closed'].includes(r.status)&&r.data?.trainingVerified&&r.data?.attendance?.some(a=>String(a.personId)===String(id)&&a.attended&&a.passed&&a.approved)))).sort((a,b)=>String(b.data?.validFrom||b.recordDate||'').localeCompare(String(a.data?.validFrom||a.recordDate||'')))[0];}
 function matrixPeople(){const f=S.filters;return S.people.filter(p=>(!f.branch||personBranch(p)===f.branch)&&(!f.query||norm(personName(p)+' '+personBranch(p)+' '+(p.jobTitle||p.job||p.gorev||'')).includes(norm(f.query)))).sort((a,b)=>personBranch(a).localeCompare(personBranch(b),'tr')||personName(a).localeCompare(personName(b),'tr'));}
 function documentStatus(r){if(!r)return {label:'Kayıt yok',status:'missing'};if(['draft','planned','open','in_progress'].includes(r.status))return {label:'Bekliyor',status:'pending'};const date=r.data?.validUntil||r.dueDate;if(date&&date<today())return {label:'Süresi geçti',status:'overdue'};if(r.status==='pending')return {label:'Doğrulama bekliyor',status:'pending'};return {label:date?displayDate(date):r.type==='training'?displayDate(r.recordDate)+' · Doğrulandı':'Süre belirtilmedi',status:done(r)?'completed':'pending'};}
 function renderMatrix(){const kinds={training:'İSG Eğitimi',medical:'Sağlık Uygunluğu',vocational:'Mesleki Yeterlilik',operator:'Operatör',firstAid:'İlk Yardım'};const people=matrixPeople();return `<table class="isg-matrix"><colgroup><col style="width:26%">${Object.keys(kinds).map(()=>'<col style="width:14.8%">').join('')}</colgroup><thead><tr><th>Personel / Şube</th>${Object.values(kinds).map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${people.length?people.map(p=>`<tr><td><button class="isg-record-title" data-act="person" data-id="${e(personId(p))}">${e(personName(p))}</button><span class="isg-row-sub">${e(personBranch(p))} · ${e(p.job||p.gorev||'')}</span></td>${Object.keys(kinds).map(kind=>{const r=latestDocument(personId(p),kind),s=documentStatus(r);return `<td><button class="isg-record-title" data-act="${r?'detail':'new-person'}" data-id="${e(r?.id||personId(p))}" data-kind="${kind}"><span class="isg-badge ${e(s.status)}">${e(s.label)}</span></button></td>`;}).join('')}</tr>`).join(''):'<tr><td colspan="6"><div class="isg-empty">Bu filtreye uygun personel bulunmuyor.</div></td></tr>'}</tbody></table>`;}
 function onAppInput(event){const key=event.target.dataset.filter;if(key!=='query')return;S.filters.query=event.target.value;const oldStart=event.target.selectionStart;render();const input=app.querySelector('[data-filter=query]');input.focus();input.setSelectionRange(oldStart,oldStart);}
 function onAppChange(event){const k=event.target.dataset.filter;if(!k)return;S.filters[k]=event.target.type==='checkbox'?event.target.checked:event.target.value;render();}
 async function onAppClick(event){const b=event.target.closest('[data-act]');if(!b||b.disabled)return;const r=S.records.find(x=>String(x.id)===b.dataset.id);switch(b.dataset.act){case'refresh':return refresh();case'tab':S.view=b.dataset.view;S.filters.type='';S.filters.deadline='';S.filters.status='';render();break;case'clear':S.filters={query:'',branch:'',status:'',from:'',to:'',type:'',archive:false,deadline:''};render();break;case'counter':S.filters.status=b.dataset.value==='review'?'pending':'';S.filters.deadline=b.dataset.value==='review'?'':b.dataset.value;S.filters.archive=false;render();break;case'new':return newPicker();case'detail':return detail(r);case'edit':return edit(r?.type,r);case'restore':return archive(r,true);case'output':return output(b);case'forms':return forms();case'person':return personDetail(b.dataset.id);case'new-person':return edit('personDocument',null,{personIds:[b.dataset.id],data:{kind:b.dataset.kind}});case'person-list':S.filters.type=S.filters.type?'':'personDocument';render();break;case'settings-save':return saveSettings(b);case'new-user':return userForm();case'access-edit':return accessForm(S.users.find(u=>String(u.id)===b.dataset.id));}}
 function closeDialog(force=false){if(dialog?.busy&&!force)return;dialog?.overlay.remove();dialog=null;document.removeEventListener('keydown',dialogKey);previousFocus?.focus?.();}
