 function modal(title,body,foot='',wide=false){closeDialog(true);previousFocus=document.activeElement;const overlay=document.createElement('div');overlay.className='isg-overlay';overlay.dataset.casePreserve='true';overlay.innerHTML=`<section role="dialog" aria-modal="true" aria-labelledby="isgDialogTitle" class="isg-dialog ${wide?'isg-wide':''}"><header class="isg-dialog-head"><h3 id="isgDialogTitle">${e(title)}</h3><button type="button" data-close aria-label="Kapat">✕</button></header><div class="isg-dialog-body">${body}</div>${foot?`<footer class="isg-dialog-foot">${foot}</footer>`:''}</section>`;/* The portal's global uppercase listener must never rewrite opaque IDs or ISG form text. */overlay.querySelectorAll('input,textarea').forEach(input=>input.dataset.casePreserve='true');document.body.appendChild(overlay);dialog={overlay,busy:false};overlay.querySelector('[data-close]').onclick=()=>closeDialog();overlay.onclick=ev=>{if(ev.target===overlay)closeDialog();};document.addEventListener('keydown',dialogKey);setTimeout(()=>overlay.querySelector('input:not([type=checkbox]),select,button')?.focus(),0);return dialog;}
