anned=JSON.parse(JSON.stringify(r.data.items||[]));function drawPlans(){const div=form.querySelector('[data-plan-items]');if(!div)return;div.innerHTML=planned.map((x,i)=>`<div class="isg-form-grid" style="margin-bottom:9px" data-plan-index="${i}"><input data-plan="title" placeholder="Yapılacak iş" value="${e(x.title)}" required><div class="isg-actions"><input data-plan="dueDate" type="date" value="${e(x.dueDate)}" style="flex:1"><button type="button" data-plan-remove="${i}">Kaldır</button></div></div>`).join('');div.oninput=ev=>{const row=ev.target.closest('[data-plan-index]');if(row&&ev.target.dataset.plan)planned[Number(row.dataset.planIndex)][ev.target.dataset.plan]=ev.target.value;};div.onclick=ev=>{const b=ev.target.closest('[data-plan-remove]');if(b){planned.splice(Number(b.dataset.planRemove),1);drawPlans();}};}
  if(type==='annualPlan'){drawPlans();form.querySelector('[data-add-plan]').onclick=()=>{planned.push({title:'',dueDate:'',status:'planned'});drawPlans();};}
