 function passwordForm(user){if(!canSettings('manageUsers'))return;const d=modal('Geçici Şifre Belirle · '+(user.name||''),'<form id="isgPasswordForm"><div class="isg-notice">Yeni şifreyi güvenli kanaldan iletin. Kullanıcı ilk girişte şifresini değiştirmek zorundadır.</div><label class="isg-field"><span>Yeni geçici şifre *</span><input type="password" name="password" minlength="6" autocomplete="new-password" required><small>En az 6 karakter; harf veya rakam zorunluluğu yoktur.</small></label></form>','<span class="isg-form-state" data-save-state></span><button data-cancel>Vazgeç</button><button type="submit" form="isgPasswordForm" class="isg-primary">Şifreyi Sıfırla</button>');d.overlay.querySelector('[data-cancel]').onclick=()=>closeDialog();const form=d.overlay.querySelector('form');form.onsubmit=async ev=>{ev.preventDefault();if(d.busy||!form.reportValidity())return;try{busy(true);await api('access-reset-password',{userId:user.id,password:form.elements.password.value});form.elements.password.value='';closeDialog(true);notice('Geçici şifre belirlendi. Kullanıcı ilk girişte değiştirecek.');}catch(err){busy(false);modalError(err);}};}
 async function medicalForm(record){
  if(!record||!can('medical'))return;const d=modal('Hekim Kaydı · '+record.title,'<div class="isg-notice">Bu içerik yalnız işyeri hekimine açıktır. Genel İSG listelerine, çıktılara ve mesajlara dahil edilmez.</div><div data-medical-body class="isg-muted">Hekim kaydı yükleniyor…</div>','<span class="isg-form-state" data-save-state></span><button data-cancel>Kapat</button><button type="submit" form="isgMedicalForm" class="isg-primary" data-medical-save disabled>Hekim Kaydını Kaydet</button>');d.overlay.querySelector('[data-cancel]').onclick=()=>closeDialog();
  try{const res=await api('medical-get',{recordId:record.id});if(dialog!==d)return;const stored=res.medical||{},m=stored.data||{};const people=S.people.filter(p=>(record.personIds||[]).map(String).includes(personId(p)));const fields=[F('assessmentDate','Muayene tarihi','date',null,true),F('assessment','Hekim değerlendirmesi','textarea'),F('restrictions','Hekim tarafından belirlenen kısıtlar','textarea'),F('doctorNote','Hekim notu','textarea'),F('nextReviewDate','Sonraki değerlendirme','date')];d.overlay.querySelector('[data-medical-body]').innerHTML=`<form id="isgMedicalForm"><div class="isg-form-grid"><label class="isg-field isg-full"><span>Personel *</span><select name="personId" required>${options(Object.fromEntries(people.map(p=>[personId(p),personName(p)])),m.personId)}</select></label>${fields.map(f=>fieldHtml(f,m[f.key])).join('')}</div></form>`;d.overlay.querySelector('[data-medical-save]').disabled=!mayEdit();const form=d.overlay.querySelector('form');form.onsubmit=async ev=>{ev.preventDefault();if(d.busy||!mayEdit()||!form.reportValidity())return;const medical={personId:form.elements.personId.value};fields.forEach(f=>medical[f.key]=form.elements.namedItem('data.'+f.key).value||'');try{busy(true);await api('medical-save',{recordId:record.id,medical,expectedRevision:stored.revision||0});closeDialog(true);notice('Hekim kaydı güvenli alana kaydedildi.');}catch(err){busy(false);modalError(err);}};}catch(err){modalError(err);}
 }
 function reset(){sessionEpoch++;uploadQueues.clear();loadSequence++;closeDialog(true);unmountSettings();refreshPromise=null;root.fdIsgDocuments?.clear?.();Object.assign(S,{records:[],people:[],branches:[],vehicles:[],kkd:[],users:[],activity:[],settings:{},permissions:{},view:'overview',filters:{query:'',branch:'',status:'',from:'',to:'',type:'',archive:false,deadline:''},loaded:false,loading:false,busy:false,error:'',company:'',revision:0});if(app){app.replaceChildren();app.style.display='none';}}
 root.openIsgApp=open;
 root.fdIsgWorkspace={open,refresh,mountSettings,unmountSettings,edit,detail,getExportModels,validateRecord,documentStatus,schemas,state:S,filtered,personName,personBranch,personId,reset,access:()=>{if(!canSettings('manageUsers'))return;return root.fdIsgSettingsOpen?.(true);},close:()=>{closeDialog();if(app)app.style.display='none';}};
